if (!value || (value < 31536000)) {
    return "N/A";
}
const diffMs = Date.now() - value;
const t=diffMs / 60000.0;// minutes
if (t < 1.0) {
    return "just now";
} else if (t < 60.0) {
    return Math.round(t) + " minutes ago";
} else if (t < 1440) {
    // < 1 day -> orange
    return Math.floor(t/60.0)+" hours ago";
} else {
    return Math.floor(t/1440)+" days ago";
}

