settings.cardCss:
.card {
    width: 100%;
    height: 100%;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    box-sizing: border-box;
    background: #f0f6ff;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Inter,
        Arial,
        sans-serif;

    color: #1f2937;
    line-height: 1.55;
    overflow: auto;
}

.card .content {
    width: 100%;
    min-height: 100%;
    padding: 14px 16px;

    display: flex;
    flex-direction: row;
    align-items: flex-start;
    justify-content: flex-start;

    box-sizing: border-box;
}

.card .content .column {
    width: 100%;
    min-width: 0;

    display: flex;
    flex-direction: column;
    justify-content: flex-start;
}

/* Title */
.card h1 {
    position: relative;

    margin: 0 0 8px 0;
    padding: 2px 0 3px 14px;

    font-size: 20px;
    font-weight: 700;
    line-height: 1.25;
    text-transform: none;
    color: #0f172a;
}

.card h1::before {
    content: "";

    position: absolute;
    top: -2px;
    bottom: -2px;
    left: 0;

    width: 4px;

    background: #1f6feb;
    border-radius: 2px;
}


/* Abstract */
.card .abstract {
    margin: 0 0 10px 0;

    font-size: 12px;
    font-weight: 500;
    line-height: 1.5;
    color: #334155;
}

/* Description container */
.card .description {
    margin: 0;

    font-size: 8px;
    line-height: 1.55;
    font-weight: 400;
    color: #1f2937;
}

/* Paragraphs contained in the description attribute */
.card .description p {
    margin: 0 0 8px 0;
}

.card .description p:last-child {
    margin-bottom: 0;
}

/* Emphasised text in entity attributes */
.card .abstract strong,
.card .description strong {
    font-weight: 700;
}

